      { when: 'SAT · 14:00–17:00', name: 'Saturday Afternoon', what: 'Bring Your Own drink', pp: 50, min: 650 },
      { when: 'SAT · 14:00–17:00', name: 'Saturday Afternoon', what: 'Bring Your Own drink & pizza', pp: 60, min: 720 },
      { when: 'SAT · 18:00–21:00 · + DEC/JAN WEEKNIGHTS', name: 'Saturday Night', what: 'Bring Your Own drink', pp: 50, min: 700 },
      { when: 'SAT · 18:00–21:00 · + DEC/JAN WEEKNIGHTS', name: 'Saturday Night', what: 'Bring Your Own drink & pizza', pp: 60, min: 840 }
